<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAllowAllScopesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowAllScopesAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowAllScopes,
 * getAllowAllScopes/allowAllScopes accessors, and isAllowAllScopesChanged with/without original.
 */
class TrustedClientAllowAllScopesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowAllScopes creates a new instance with the AllowAllScopes set
     * from a string value, and getAllowAllScopes returns the primitive string.
     */
    public function testWithAllowAllScopesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowAllScopesAccessorUnitTest();

        // Act
        $result = $holder->withAllowAllScopes(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isAllowAllScopes());
    }
    /**
     * Asserts that withallowAllScopes has access to the value object
     * from a string value, and getAllowAllScopes returns the primitive string.
     */
    public function testWithAllowAllScopesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowAllScopesAccessorUnitTest();

        // Act
        $result = $holder->withAllowAllScopes(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->allowAllScopes()->value());
    }
    public function testChangedAllowAllScopes(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowAllScopesAccessorUnitTest();
        $original = $holder->withAllowAllScopes(true);
        $same = $holder->withAllowAllScopes(true);
        $modified = $holder->withAllowAllScopes(false);

        // Act
        $unchanged = $holder->isAllowAllScopesChanged();
        $withSame = $original->isAllowAllScopesChanged($same);
        $withDiferent = $original->isAllowAllScopesChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAllowAllScopesAccessorUnitTest
{
    use TrustedClientAllowAllScopesAccessor;
}
